// Matchday Call partner dashboard. Plain JS, no build step.
// Data comes from window.SIM (data/data.js, generated by sim/simulate.js).
// URL options: ?autoplay=1  &seconds=16 (replay length)  &demo=0 (hide the DEMO DATA tag)
(function () {
  "use strict";
  var SIM = window.SIM;
  var params = new URLSearchParams(location.search);
  var REPLAY_SECONDS = Number(params.get("seconds")) || 16;
  if (params.get("demo") === "0") document.getElementById("demo-tag").hidden = true;

  // ---- timeline: 0..45 first half, 46..48 half-time, 49..97 second half, 98..117 after full time
  var T = [], m, i;
  for (m = 0; m <= 45; m++) T.push({ phase: "1H", clock: m === 0 ? "KICK-OFF" : m + "'" });
  for (i = 0; i < 3; i++) T.push({ phase: "HT", clock: "HALF-TIME" });
  for (m = 46; m <= 94; m++) T.push({ phase: "2H", clock: m > 90 ? "90+" + (m - 90) + "'" : m + "'" });
  for (i = 1; i <= 20; i++) T.push({ phase: "POST", clock: "FT +" + i + " MIN" });
  var N = T.length, FT = 97, s = SIM.series;
  var goals = [{ i: 18, team: "ARS", clock: "18'" }, { i: 57, team: "CHE", clock: "54'" }, { i: 80, team: "ARS", clock: "77'" }];

  var cum = { su: [], pl: [], sc: [], calls: [] }, a = 0, b = 0, c = 0, d = 0;
  for (i = 0; i < N; i++) {
    a += s.signups[i]; b += s.started[i]; c += s.scans[i]; d += s.calls[i];
    cum.su.push(a); cum.pl.push(b); cum.sc.push(c); cum.calls.push(d);
  }
  goals.forEach(function (g) { g.lift = s.calls[g.i] / ((s.calls[g.i - 3] + s.calls[g.i - 2] + s.calls[g.i - 1]) / 3); });
  var avgLift = goals.reduce(function (x, g) { return x + g.lift; }, 0) / goals.length;
  var postShare = (cum.su[FT + 10] - cum.su[FT]) / cum.su[N - 1];

  function fmt(n) { return Math.round(n).toLocaleString("en-US"); }
  function pct(x, y) { return y > 0 ? (x / y * 100).toFixed(1) + "%" : "—"; }
  function $(id) { return document.getElementById(id); }
  function setText(id, v) { $(id).textContent = v; }
  function el(tag, cls, text) { var e = document.createElement(tag); if (cls) e.className = cls; if (text != null) e.textContent = text; return e; }

  // ---- static parts
  var F = SIM.funnel;
  setText("final-signups", fmt(F.signedUp));
  setText("final-conv", pct(F.signedUp, F.started));
  setText("new-share", Math.round(SIM.newShare * 100) + "%");
  setText("i-goal", "×" + avgLift.toFixed(1));
  setText("i-post", Math.round(postShare * 100) + "%");

  var steps = [
    ["Scanned the QR code", F.scanned], ["Picked a side and started", F.started],
    ["Made at least one call", F.called], ["Made a forecast", F.forecast],
    ["Stayed to full time", F.sawFT], ["Saved points with an email", F.signedUp]
  ];
  steps.forEach(function (st, j) {
    var last = j === steps.length - 1, color = last ? "var(--green)" : "var(--cyan)";
    var row = el("div", "f-row"), top = el("div", "line-top");
    top.appendChild(el("span", null, st[0]));
    var right = el("span", "row gap10");
    if (j > 0) right.appendChild(el("span", "muted small", pct(st[1], steps[j - 1][1]) + " of prev."));
    var num = el("span", "num", fmt(st[1])); num.style.color = color; right.appendChild(num);
    top.appendChild(right); row.appendChild(top);
    var track = el("div", "bar-track"), fill = el("div", "bar-fill");
    fill.style.width = (st[1] / steps[0][1] * 100).toFixed(1) + "%"; fill.style.background = color;
    track.appendChild(fill); row.appendChild(track);
    $("funnel").appendChild(row);
  });

  var ch = SIM.channels, maxRate = 0;
  ch.forEach(function (x) { maxRate = Math.max(maxRate, x[2] / x[1]); });
  ch.forEach(function (x, j) {
    var r = x[2] / x[1], color = j === 0 ? "var(--cyan)" : "var(--lilac)";
    var row = el("div", "c-row"), top = el("div", "line-top");
    top.appendChild(el("span", null, x[0]));
    var num = el("span", "num", (r * 100).toFixed(1) + "%"); num.style.color = color; num.style.fontSize = "22px";
    top.appendChild(num); row.appendChild(top);
    var track = el("div", "bar-track"), fill = el("div", "bar-fill");
    track.style.height = "8px"; fill.style.width = (r / maxRate * 100).toFixed(1) + "%"; fill.style.background = color;
    track.appendChild(fill); row.appendChild(track);
    row.appendChild(el("span", "muted", fmt(x[1]) + " scans · " + fmt(x[2]) + " sign-ups")).style.fontSize = "12px";
    $("channels").appendChild(row);
  });
  var walk = ch.slice(1).reduce(function (acc, x) { return [acc[0] + x[1], acc[1] + x[2]]; }, [0, 0]);
  setText("i-room", "×" + ((ch[0][2] / ch[0][1]) / (walk[1] / walk[0])).toFixed(1));

  // ---- chart
  var NS = "http://www.w3.org/2000/svg", svg = $("chart");
  var X0 = 60, X1 = 1130, YT = 56, YB = 316, STEP = (X1 - X0) / N, BW = STEP * 0.62;
  function xAt(k) { return X0 + (k + 0.5) * STEP; }
  function yL(v) { return YB - v / 12000 * (YB - YT); }
  function yR(v) { return YB - v / 4000 * (YB - YT); }
  function svgEl(tag, attrs, style, text) {
    var e = document.createElementNS(NS, tag);
    for (var k in attrs) e.setAttribute(k, attrs[k]);
    if (style) e.setAttribute("style", style);
    if (text != null) e.textContent = text;
    svg.appendChild(e); return e;
  }
  var bnd = function (k) { return X0 + k * STEP; };
  svgEl("rect", { x: bnd(46), y: YT, width: 3 * STEP, height: YB - YT }, "fill: rgba(205,184,209,0.07)");
  svgEl("rect", { x: bnd(FT + 1), y: YT, width: X1 - bnd(FT + 1), height: YB - YT }, "fill: rgba(0,255,133,0.08)");
  [0, 3000, 6000, 9000, 12000].forEach(function (v, k) {
    svgEl("line", { x1: X0, x2: X1, y1: yL(v), y2: yL(v) }, "stroke: #5C2A63; stroke-width: " + (k ? "1; stroke-dasharray: 3 5" : "1.5"));
    svgEl("text", { x: 50, y: yL(v) + 4 }, "text-anchor: end", v ? v / 1000 + "K" : "0");
  });
  [1000, 2000, 3000, 4000].forEach(function (v) { svgEl("text", { x: 1140, y: yR(v) + 4 }, "fill: #00FF85", v / 1000 + "K"); });
  var barsFut = svgEl("path", {}, "fill: #C9A2FF; opacity: 0.12");
  var barsPast = svgEl("path", {}, "fill: #C9A2FF; opacity: 0.6");
  var liveArea = svgEl("path", {}, "fill: rgba(4,245,255,0.14)");
  var liveLine = svgEl("polyline", {}, "fill: none; stroke: #04F5FF; stroke-width: 2.5; stroke-linejoin: round");
  var suGlow = svgEl("polyline", {}, "fill: none; stroke: rgba(0,255,133,0.28); stroke-width: 9; stroke-linejoin: round; stroke-linecap: round");
  var suLine = svgEl("polyline", {}, "fill: none; stroke: #00FF85; stroke-width: 3.5; stroke-linejoin: round; stroke-linecap: round");
  goals.forEach(function (g) {
    svgEl("line", { x1: xAt(g.i), x2: xAt(g.i), y1: 48, y2: YB }, "stroke: #FF5C93; stroke-width: 1.5; stroke-dasharray: 4 4");
    svgEl("text", { x: xAt(g.i), y: 40, "class": "ev" }, "text-anchor: middle; fill: #FF5C93", "GOAL " + g.team + " " + g.clock);
  });
  svgEl("text", { x: bnd(47.5), y: 40, "class": "ev" }, "text-anchor: middle", "HT");
  svgEl("line", { x1: bnd(FT + 1), x2: bnd(FT + 1), y1: 48, y2: YB }, "stroke: #F3F6F9; stroke-width: 1.5");
  svgEl("text", { x: bnd(FT + 1), y: 40, "class": "ev" }, "text-anchor: middle; fill: #F3F6F9", "FULL TIME");
  svgEl("text", { x: (bnd(FT + 1) + X1) / 2, y: 76, "class": "ev" }, "text-anchor: middle; fill: #00FF85; font-size: 15px", "SIGN-UP WAVE");
  var playLine = svgEl("line", { y1: 50, y2: YB }, "stroke: #F3F6F9; stroke-width: 1.5; opacity: 0.75");
  var liveDot = svgEl("circle", { r: 5 }, "fill: #04F5FF; stroke: #1A0020; stroke-width: 2");
  var suDot = svgEl("circle", { r: 6 }, "fill: #00FF85; stroke: #1A0020; stroke-width: 2");
  [[0, "KO"], [15, "15'"], [30, "30'"], [47, "HT"], [63, "60'"], [78, "75'"], [107, "+10 min"]].forEach(function (t) {
    svgEl("text", { x: xAt(t[0]), y: 340 }, "text-anchor: middle", t[1]);
  });
  svgEl("text", { x: bnd(FT + 1), y: 340 }, "text-anchor: middle; fill: #F3F6F9", "FT");
  svgEl("text", { x: X1, y: 340 }, "text-anchor: end", "+20 min");

  // ---- dynamic state
  var idx = N - 1, timer = null, hold = 0;
  var holds = {}; goals.forEach(function (g) { holds[g.i] = 10; }); holds[46] = 6; holds[FT] = 12;
  var scrub = $("scrub"); scrub.max = N - 1;

  function render() {
    var past = "", fut = "", lp = [], sp = [], k;
    for (k = 0; k < N; k++) {
      if (s.calls[k] > 0) {
        var bx = xAt(k) - BW / 2;
        var seg = "M" + bx.toFixed(1) + " " + YB + "V" + yL(s.calls[k]).toFixed(1) + "H" + (bx + BW).toFixed(1) + "V" + YB + "Z";
        if (k <= idx) past += seg; else fut += seg;
      }
      if (k <= idx) { lp.push(xAt(k).toFixed(1) + "," + yL(s.live[k]).toFixed(1)); sp.push(xAt(k).toFixed(1) + "," + yR(cum.su[k]).toFixed(1)); }
    }
    barsPast.setAttribute("d", past); barsFut.setAttribute("d", fut);
    liveArea.setAttribute("d", "M" + xAt(0).toFixed(1) + "," + YB + " L" + lp.join(" L") + " L" + xAt(idx).toFixed(1) + "," + YB + " Z");
    liveLine.setAttribute("points", lp.join(" "));
    suGlow.setAttribute("points", sp.join(" ")); suLine.setAttribute("points", sp.join(" "));
    var px = xAt(idx);
    playLine.setAttribute("x1", px); playLine.setAttribute("x2", px);
    liveDot.setAttribute("cx", px); liveDot.setAttribute("cy", yL(s.live[idx]));
    suDot.setAttribute("cx", px); suDot.setAttribute("cy", yR(cum.su[idx]));

    var peak = 0, peakI = 0;
    for (k = 0; k <= idx; k++) if (s.live[k] > peak) { peak = s.live[k]; peakI = k; }
    var players = cum.pl[idx], scans = cum.sc[idx], su = cum.su[idx];
    setText("clock", T[idx].clock);
    setText("k-scans", fmt(scans)); setText("k-players", fmt(players)); setText("k-playrate", pct(players, scans));
    setText("k-live", fmt(s.live[idx])); setText("k-peak", fmt(peak)); setText("k-peakclock", T[peakI].clock.toLowerCase());
    setText("k-calls", fmt(cum.calls[idx])); setText("k-perplayer", players > 0 ? (cum.calls[idx] / players).toFixed(1) : "0");
    setText("k-signups", fmt(su)); setText("k-conv", pct(su, players));
    setText("r-live", fmt(s.live[idx])); setText("r-calls", fmt(s.calls[idx])); setText("r-su", fmt(su));

    var goal = null; goals.forEach(function (g) { if (idx >= g.i && idx <= g.i + 6) goal = g; });
    var tag, text, color = "var(--muted)", cls = "moment";
    if (goal) { tag = "GOAL " + goal.team + " " + goal.clock; text = "calls jump ×" + goal.lift.toFixed(1) + " in a minute"; color = "var(--pink)"; cls += " goal"; }
    else if (T[idx].phase === "HT") { tag = "HALF-TIME"; text = "second-half forecasts open"; }
    else if (idx === FT) { tag = "FULL TIME"; text = "results + save-your-points screen"; color = "var(--green)"; cls += " wave"; }
    else if (idx > FT) { tag = timer || idx < N - 1 ? "SIGN-UP WAVE" : "FULL REPORT"; text = fmt(su - cum.su[FT]) + " saved points since the whistle"; color = "var(--green)"; cls += " wave"; }
    else { tag = "LIVE"; text = T[idx].clock + " · " + fmt(s.live[idx]) + " playing"; color = "var(--cyan)"; }
    $("moment").className = cls; setText("moment-tag", tag); $("moment-tag").style.color = color; setText("moment-text", text);

    scrub.value = idx;
    $("icon-play").style.display = timer ? "none" : ""; $("icon-pause").style.display = timer ? "" : "none";
    setText("play-label", timer ? "PAUSE" : (idx >= N - 1 ? "REPLAY MATCH" : "PLAY"));
  }

  function stop() { if (timer) { clearInterval(timer); timer = null; } render(); }
  function play() {
    if (timer) return;
    if (idx >= N - 1) idx = 0;
    hold = 0;
    var ms = Math.max(25, Math.round(REPLAY_SECONDS * 1000 / (N + 40)));
    timer = setInterval(function () {
      if (hold > 0) { hold--; return; }
      if (idx + 1 >= N - 1) { idx = N - 1; stop(); return; }
      idx++; if (holds[idx]) hold = holds[idx];
      render();
    }, ms);
    render();
  }
  $("play").addEventListener("click", function () { if (timer) stop(); else play(); });
  scrub.addEventListener("input", function () { if (timer) { clearInterval(timer); timer = null; } idx = Number(scrub.value); render(); });

  render();
  if (params.get("autoplay") === "1") play();
})();
